import React, { useEffect, useMemo, useState } from 'react';
import ExcursionCard from '../../components/Card/ExcursionCard';
import Filter from '../../components/Filter/Filter';
import { getTours } from '../../services/tourService';
import {
  getCountries,
  getCategories,
  getTourOperators,
  getTags
} from '../../services/filterService';
import './CatalogPage.css';

const CatalogPage = () => {
  const [filters, setFilters] = useState({});
  const [filterOptions, setFilterOptions] = useState(null);

  const [excursions, setExcursions] = useState([]);
  const [loading, setLoading] = useState(true);

  const [favorites, setFavorites] = useState(new Set());
  const [cart, setCart] = useState(new Set());

  // 🔹 Стабильный ключ для useEffect
  const filtersKey = useMemo(() => {
    return JSON.stringify(filters);
  }, [filters]);

  // 🔹 Загружаем фильтры 1 раз
  useEffect(() => {
    loadFilters();
    loadTours({});
  }, []);

  // 🔹 Загружаем туры ТОЛЬКО когда реально меняются фильтры
  useEffect(() => {
    if (!filterOptions) return;
    loadTours(filters);
  }, [filtersKey]);

  const loadFilters = async () => {
    try {
      const [countries, categories, operators, tags] = await Promise.all([
        getCountries(),
        getCategories(),
        getTourOperators(),
        getTags()
      ]);

      setFilterOptions({
        Рейтинг: [5, 4, 3, 2, 1],
        Страна: countries,
        Категория: categories,
        Туроператор: operators,
        Тэги: tags
      });
    } catch (e) {
      console.error('Ошибка загрузки фильтров', e);
    }
  };

  const loadTours = async (activeFilters = {}) => {
    try {
      setLoading(true);

      const params = {};

      if (activeFilters['Страна']?.size)
        params.countryId = [...activeFilters['Страна']];

      if (activeFilters['Категория']?.size)
        params.categoryId = [...activeFilters['Категория']];

      if (activeFilters['Туроператор']?.size)
        params.operatorId = [...activeFilters['Туроператор']];

      if (activeFilters['Тэги']?.size)
        params.tagId = [...activeFilters['Тэги']];

      const data = await getTours(params);
      setExcursions(data);
    } catch (e) {
      console.error('Ошибка загрузки туров', e);
    } finally {
      setLoading(false);
    }
  };

  const toggleFavorite = (id) => {
    setFavorites(prev => {
      const s = new Set(prev);
      s.has(id) ? s.delete(id) : s.add(id);
      return s;
    });
  };

  const toggleCart = (id) => {
    setCart(prev => {
      const s = new Set(prev);
      s.has(id) ? s.delete(id) : s.add(id);
      return s;
    });
  };

  if (!filterOptions || loading) {
    return <div className="catalog-loading">Загрузка...</div>;
  }

  return (
    <div className="catalog-wrapper">
      <div className="layout-catalog">
        <Filter filters={filterOptions} onChange={setFilters} />

        <main className="content-catalog">
          <div className="catalog-grid">
            {excursions.map(excursion => (
              <ExcursionCard
                key={excursion.id}
                excursion={excursion}
                isFavorite={favorites.has(excursion.id)}
                inCart={cart.has(excursion.id)}
                onToggleFavorite={toggleFavorite}
                onToggleCart={toggleCart}
              />
            ))}
          </div>

          {excursions.length === 0 && (
            <div className="no-results">
              Ничего не найдено
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default CatalogPage;
